@Service
public class OrderService {

    @Autowired private OrderRepository orderRepo;
    @Autowired private AuditService auditService;  // separate bean — proxy works
    @Autowired private InventoryService inventoryService;

    @Transactional  // outer transaction — rolls back if inventory fails
    public Order placeOrder(OrderRequest request) {
        Order order = new Order(request);
        orderRepo.save(order);

        // auditService is a separate bean, so REQUIRES_NEW proxy kicks in:
        auditService.logEvent("ORDER_ATTEMPT", request.getUserId());
        // ↑ This commits in its own independent transaction immediately.

        // If this throws, outer transaction rolls back (order is not saved),
        // but the audit log record IS already committed:
        inventoryService.reserveStock(request);

        auditService.logEvent("ORDER_CONFIRMED", request.getUserId());
        return order;
    }
}

@Service
public class AuditService {

    @Autowired private AuditLogRepository auditRepo;

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void logEvent(String eventType, Long userId) {
        auditRepo.save(new AuditLog(eventType, userId, LocalDateTime.now()));
        // This inner transaction commits as soon as this method returns,
        // independent of the outer transaction's fate.
    }
}

