@Service
public class ProductService {

    @Autowired private ProductRepository productRepo;

    @Transactional(readOnly = true)
    public List<Product> getAllProducts() {
        // readOnly = true:
        // - Hibernate skips dirty-checking at flush time (no snapshot comparison)
        // - Some databases route to read replicas
        // - Slightly faster for large result sets
        return productRepo.findAll();
    }

    @Transactional
    public Product decrementStock(Long productId, int quantity) {
        Product product = productRepo.findById(productId)
            .orElseThrow(() -> new RuntimeException("Product not found"));

        if (product.getStockCount() < quantity) {
            throw new RuntimeException("Insufficient stock");
        }

        product.setStockCount(product.getStockCount() - quantity);

        try {
            return productRepo.save(product);
            // Hibernate generates:
            // UPDATE products SET stock_count=?, version=version+1
            // WHERE id=? AND version=?  ← optimistic lock check
        } catch (ObjectOptimisticLockingFailureException e) {
            throw new ConcurrentModificationException(
                "Product was modified by another user. Please retry.");
        }
    }
}

